#!/usr/bin/env python3
"""NXT CAMP: inscrição mais curta no celular, Pix e comprovante na mesma tela, preenchimento guardado
na volta do banco, progresso em 3 passos com aviso de voltar para o comprovante e vários adolescentes com um pagamento só (17/11/2026). Só arquivos da página:
não mexe em api-inscricao.php nem no painel. Uso no servidor:
  python3 nxt-inscricao-celular.py --verificar   # só confere, não grava nada
  python3 nxt-inscricao-celular.py               # publica, com backup"""
import base64, hashlib, os, shutil, sys, tempfile
from pathlib import Path
NXT=Path('/home/novaigre/public_html/next/camp-sbgp1-nov26')
OLD={'inscricao.html': '0310331339662687427b408b0dfacb081e06a8b75e0085b9400f5aa1bbc5691a', 'assets/inscricao.js': '322a360eabedb4e8300e7f385b0bd7f7d493c9660e45f193f725b47dac181ab8', 'assets/inscricao.css': '5f2b5112b949920fa70326221d12b26da9c2528f81584e50f8a29f4efdf8ca11'}
NEW={
 'inscricao.html':base64.b64decode(''),
 'assets/inscricao.js':base64.b64decode(''),
 'assets/inscricao.css':base64.b64decode(''),
 'assets/vendor/qrcode-generator-2.0.4.js':base64.b64decode(''),
}
sha=lambda b:hashlib.sha256(b).hexdigest()
for rel,h in OLD.items():
    p=NXT/rel
    if not p.is_file() or p.is_symlink(): sys.exit(f'ABORTADO: arquivo ausente: {p}')
    if sha(p.read_bytes())!=h: sys.exit(f'ABORTADO: {rel} de produção mudou (sha {sha(p.read_bytes())})')
for rel in NEW:
    p=NXT/rel
    if rel not in OLD and p.exists(): sys.exit(f'ABORTADO: {rel} já existe no servidor')
if '--verificar' in sys.argv:
    for rel,d in NEW.items(): print('OK',rel,sha(d))
    print('VERIFICADO: nada foi gravado'); sys.exit(0)
backup=Path(tempfile.mkdtemp(prefix='nib-nxt-inscricao-celular-',dir='/home/novaigre/nib-manutencao'))
for rel,d in NEW.items():
    p=NXT/rel
    p.parent.mkdir(parents=True,exist_ok=True)
    if p.exists():
        dest=backup/rel; dest.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,dest)
    fd,tmp=tempfile.mkstemp(prefix='.nib-celular-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f: f.write(d)
        if p.exists(): shutil.copymode(p,tmp)
        else: os.chmod(tmp,0o644)
        os.replace(tmp,p)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)
    assert p.read_bytes()==d; print('PUBLICADO',p,sha(d))
print('BACKUP:',backup)
print('Para desfazer: copie os arquivos do BACKUP de volta e apague assets/vendor/qrcode-generator-2.0.4.js')
